package com.library.dao;
import com.library.enums.Role; import com.library.model.*; import com.library.util.DBConnection;
import java.sql.*; import java.time.LocalDate; import java.util.*;
public class UserDAO {
 public Optional<User> findByEmail(String email){String sql="SELECT u.*,m.member_id,m.phone,m.course,m.department,m.semester,m.registration_date,a.employee_id FROM users u LEFT JOIN member_details m ON m.user_id=u.user_id LEFT JOIN admin_details a ON a.user_id=u.user_id WHERE u.email=?";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setString(1,email);try(ResultSet r=p.executeQuery()){return r.next()?Optional.of(map(r)):Optional.empty();}}catch(SQLException e){throw new RuntimeException("Unable to load user.",e);}}
 public Optional<User> findByMemberId(long memberId){String sql="SELECT u.*,m.member_id,m.phone,m.course,m.department,m.semester,m.registration_date FROM users u JOIN member_details m ON m.user_id=u.user_id WHERE m.member_id=?";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setLong(1,memberId);try(ResultSet r=p.executeQuery()){return r.next()?Optional.of(map(r)):Optional.empty();}}catch(SQLException e){throw new RuntimeException("Unable to load student.",e);}}
 public List<Member> findMembers(String term){String sql="SELECT u.*,m.* FROM users u JOIN member_details m ON m.user_id=u.user_id WHERE u.name LIKE ? OR u.email LIKE ? OR m.phone LIKE ? OR CAST(m.member_id AS CHAR) LIKE ? ORDER BY u.name";List<Member> out=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){for(int i=1;i<=4;i++)p.setString(i,"%"+term+"%");try(ResultSet r=p.executeQuery()){while(r.next())out.add((Member)map(r));}}catch(SQLException e){throw new RuntimeException("Unable to load members.",e);}return out;}
 public Member findMember(long memberId){String sql="SELECT u.*,m.* FROM users u JOIN member_details m ON m.user_id=u.user_id WHERE m.member_id=?";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setLong(1,memberId);try(ResultSet r=p.executeQuery()){if(r.next())return (Member)map(r);}}catch(SQLException e){throw new RuntimeException("Unable to load member.",e);}return null;}
 public void insertMember(Member m){String u="INSERT INTO users(name,email,password_hash,role,status) VALUES(?,?,?,'MEMBER','ACTIVE')", d="INSERT INTO member_details(member_id,user_id,phone,course,department,semester,registration_date) VALUES(?,?,?,?,?,?,?)";try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try(PreparedStatement up=c.prepareStatement(u,Statement.RETURN_GENERATED_KEYS)){up.setString(1,m.getName());up.setString(2,m.getEmail());up.setString(3,m.getPasswordHash());up.executeUpdate();try(ResultSet k=up.getGeneratedKeys()){k.next();m.setUserId(k.getLong(1));}try(PreparedStatement dp=c.prepareStatement(d)){dp.setLong(1,m.getMemberId());dp.setLong(2,m.getUserId());dp.setString(3,m.getPhone());dp.setString(4,m.getCourse());dp.setString(5,m.getDepartment());dp.setInt(6,m.getSemester());dp.setDate(7,java.sql.Date.valueOf(m.getRegistrationDate()));dp.executeUpdate();}c.commit();}catch(SQLException e){c.rollback();throw e;}}catch(SQLException e){throw new RuntimeException("Unable to add student. Enrollment number or email may already exist.",e);}}
 public void updateMember(Member m){String sql="UPDATE users u JOIN member_details d ON d.user_id=u.user_id SET u.name=?,u.email=?,d.phone=?,d.course=?,d.department=?,d.semester=? WHERE d.member_id=?";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setString(1,m.getName());p.setString(2,m.getEmail());p.setString(3,m.getPhone());p.setString(4,m.getCourse());p.setString(5,m.getDepartment());p.setInt(6,m.getSemester());p.setLong(7,m.getMemberId());if(p.executeUpdate()==0)throw new RuntimeException("Member not found.");}catch(SQLException e){throw new RuntimeException("Unable to update member.",e);}}
 public void setMemberStatus(long id,String status){String sql="UPDATE users u JOIN member_details d ON d.user_id=u.user_id SET u.status=? WHERE d.member_id=?";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setString(1,status);p.setLong(2,id);p.executeUpdate();}catch(SQLException e){throw new RuntimeException("Unable to update member status.",e);}} public void updatePassword(long userId,String passwordHash){try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE users SET password_hash=? WHERE user_id=?")){p.setString(1,passwordHash);p.setLong(2,userId);if(p.executeUpdate()!=1)throw new RuntimeException("Account not found.");}catch(SQLException e){throw new RuntimeException("Unable to change password.",e);}}
 private User map(ResultSet r)throws SQLException {Role role=Role.valueOf(r.getString("role"));if(role==Role.ADMIN)return new Admin(r.getLong("user_id"),r.getString("name"),r.getString("email"),r.getString("password_hash"),r.getString("status"),r.getString("employee_id"));java.sql.Date date=r.getDate("registration_date");return new Member(r.getLong("user_id"),r.getString("name"),r.getString("email"),r.getString("password_hash"),r.getString("status"),r.getLong("member_id"),r.getString("phone"),r.getString("course"),r.getString("department"),r.getInt("semester"),date==null?null:date.toLocalDate());}
}
